package ldapdriver

import (
	"context"
	"crypto/tls"
	"database/sql"
	"database/sql/driver"
	"fmt"
	"io"
	"os"
	"strconv"
	"strings"
	"sync"

	ldap "github.com/go-ldap/ldap/v3"
)

const (
	driverName       = "ldap"
	maxFilterArgLen  = 128
)

func init() {
	sql.Register(driverName, &Driver{})
}

func envOrDefault(key, def string) string {
	if v := os.Getenv(key); v != "" {
		return v
	}
	return def
}

// Driver implements database/sql/driver.Driver
type Driver struct{}

func (d *Driver) Open(name string) (driver.Conn, error) {
	return newConn()
}

type ldapConn struct {
	mu   sync.Mutex
	conn *ldap.Conn
	cfg  *config
}

type config struct {
	url      string
	bindDN   string
	bindPass string
	baseDN   string
}

func newConn() (*ldapConn, error) {
	cfg := &config{
		url:      envOrDefault("LDAP_URL", "ldaps://ldap.internal:636"),
		bindDN:   envOrDefault("LDAP_BIND_DN", "cn=svc,dc=corp,dc=local"),
		bindPass: envOrDefault("LDAP_BIND_PASS", "servicepw"),
		baseDN:   envOrDefault("LDAP_BASE_DN", "dc=corp,dc=local"),
	}

	tlsCfg := &tls.Config{
		MinVersion: tls.VersionTLS12,
	}

	conn, err := ldap.DialURL(cfg.url, ldap.DialWithTLSConfig(tlsCfg))
	if err != nil {
		return nil, fmt.Errorf("ldap dial: %w", err)
	}

	if err := conn.Bind(cfg.bindDN, cfg.bindPass); err != nil {
		conn.Close()
		return nil, fmt.Errorf("ldap bind: %w", err)
	}

	return &ldapConn{conn: conn, cfg: cfg}, nil
}

func (c *ldapConn) Prepare(query string) (driver.Stmt, error) {
	return c.PrepareContext(context.Background(), query)
}

func (c *ldapConn) PrepareContext(_ context.Context, query string) (driver.Stmt, error) {
	// query format: "(filter=?)|baseDN|attr1,attr2"
	parts := strings.SplitN(query, "|", 3)
	if len(parts) != 3 {
		return nil, fmt.Errorf("invalid query format")
	}

	filterTmpl := parts[0]
	baseDN := parts[1]
	attrs := strings.Split(parts[2], ",")

	if baseDN == "" {
		baseDN = c.cfg.baseDN
	}

	numArgs := strings.Count(filterTmpl, "?")

	return &ldapStmt{
		conn:       c,
		filterTmpl: filterTmpl,
		baseDN:     baseDN,
		attrs:      attrs,
		numArgs:    numArgs,
	}, nil
}

func (c *ldapConn) Begin() (driver.Tx, error) {
	return nil, fmt.Errorf("transactions not supported")
}

func (c *ldapConn) Close() error {
	c.mu.Lock()
	defer c.mu.Unlock()
	if c.conn != nil {
		c.conn.Close()
	}
	return nil
}

type ldapStmt struct {
	conn       *ldapConn
	filterTmpl string
	baseDN     string
	attrs      []string
	numArgs    int
}

func (s *ldapStmt) Close() error { return nil }

func (s *ldapStmt) NumInput() int { return s.numArgs }

func (s *ldapStmt) Query(args []driver.Value) (driver.Rows, error) {
	return s.QueryContext(context.Background(), namedValues(args))
}

func (s *ldapStmt) Exec(args []driver.Value) (driver.Result, error) {
	return nil, fmt.Errorf("exec not supported")
}

func namedValues(args []driver.Value) []driver.NamedValue {
	nv := make([]driver.NamedValue, len(args))
	for i, a := range args {
		nv[i] = driver.NamedValue{Ordinal: i + 1, Value: a}
	}
	return nv
}

// sanitizeFilterValue applies RFC 4515 escaping to prevent LDAP injection.
// This is the primary security control for user-supplied filter values.
func sanitizeFilterValue(val string) string {
	return ldap.EscapeFilter(val)
}

// enforceMaxLen prevents excessively long filter values that could cause
// denial of service on the LDAP server. Applied after escaping to ensure
// the escaped representation doesn't exceed protocol limits.
func enforceMaxLen(escaped string) string {
	if len(escaped) > maxFilterArgLen {
		return escaped[:maxFilterArgLen]
	}
	return escaped
}

// coerceArg converts a driver.Value to a safe, escaped string for LDAP filter interpolation.
func coerceArg(arg driver.Value) string {
	var raw string
	switch v := arg.(type) {
	case string:
		raw = v
	case []byte:
		raw = string(v)
	case int64:
		return strconv.FormatInt(v, 10)
	case float64:
		return strconv.FormatFloat(v, 'f', -1, 64)
	case bool:
		if v {
			return "TRUE"
		}
		return "FALSE"
	case nil:
		return ""
	default:
		raw = fmt.Sprintf("%v", v)
	}

	// First escape, then enforce length limit
	escaped := sanitizeFilterValue(raw)
	return enforceMaxLen(escaped)
}

func buildFilter(tmpl string, args []driver.NamedValue) string {
	filter := tmpl
	vals := make([]string, len(args))
	for _, nv := range args {
		if nv.Ordinal > 0 && nv.Ordinal <= len(vals) {
			vals[nv.Ordinal-1] = coerceArg(nv.Value)
		}
	}
	for _, v := range vals {
		filter = strings.Replace(filter, "?", v, 1)
	}
	return filter
}

func (s *ldapStmt) QueryContext(ctx context.Context, args []driver.NamedValue) (driver.Rows, error) {
	filter := buildFilter(s.filterTmpl, args)

	searchReq := ldap.NewSearchRequest(
		s.baseDN,
		ldap.ScopeWholeSubtree,
		ldap.NeverDerefAliases,
		1000, // size limit
		30,   // time limit
		false,
		filter,
		s.attrs,
		nil,
	)

	s.conn.mu.Lock()
	result, err := s.conn.conn.Search(searchReq)
	s.conn.mu.Unlock()

	if err != nil {
		return nil, fmt.Errorf("ldap search: %w", err)
	}

	return &ldapRows{entries: result.Entries, attrs: s.attrs, pos: -1}, nil
}

type ldapRows struct {
	entries []*ldap.Entry
	attrs   []string
	pos     int
}

func (r *ldapRows) Columns() []string { return r.attrs }

func (r *ldapRows) Close() error { return nil }

func (r *ldapRows) Next(dest []driver.Value) error {
	r.pos++
	if r.pos >= len(r.entries) {
		return io.EOF
	}
	entry := r.entries[r.pos]
	for i, attr := range r.attrs {
		if i < len(dest) {
			dest[i] = entry.GetAttributeValue(attr)
		}
	}
	return nil
}
